const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let sign = 1;
        if (buffer[offset] === 45) { // '-'
            sign = -1;
            offset++;
        }
        let res = 0;
        while (offset < buffer.length && buffer[offset] >= 48 && buffer[offset] <= 57) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res * sign;
    }

    const N = readInt();
    if (N === null) return;

    // Tendas: 1 a N. Palácio: 0.
    const X = new Int32Array(N + 1);
    const Y = new Int32Array(N + 1);
    X[0] = 0;
    Y[0] = 0;

    for (let i = 1; i <= N; i++) {
        X[i] = readInt();
        Y[i] = readInt();
    }

    const M = (N * (N + 1)) >> 1; // N*(N-1)/2 + N arestas
    const dist = new Int32Array(M);
    const uEdge = new Uint16Array(M);
    const vEdge = new Uint16Array(M);

    let edgeCount = 0;
    // Arestas de 0 para tendas
    for (let i = 1; i <= N; i++) {
        const dx = X[i];
        const dy = Y[i];
        dist[edgeCount] = dx * dx + dy * dy;
        uEdge[edgeCount] = 0;
        vEdge[edgeCount] = i;
        edgeCount++;
    }

    // Arestas entre tendas
    for (let i = 1; i <= N; i++) {
        const xi = X[i];
        const yi = Y[i];
        for (let j = i + 1; j <= N; j++) {
            const dx = xi - X[j];
            const dy = yi - Y[j];
            dist[edgeCount] = dx * dx + dy * dy;
            uEdge[edgeCount] = i;
            vEdge[edgeCount] = j;
            edgeCount++;
        }
    }

    // Radix sort de 3 passes (base 1024, 10 bits por passe, cobrindo até 30 bits: 2^30 > 8*10^8)
    let p = new Int32Array(M);
    let pNext = new Int32Array(M);
    for (let i = 0; i < M; i++) p[i] = i;

    const count = new Int32Array(1024);

    for (let shift = 0; shift < 30; shift += 10) {
        count.fill(0);
        for (let i = 0; i < M; i++) {
            const key = (dist[p[i]] >> shift) & 1023;
            count[key]++;
        }
        for (let i = 1; i < 1024; i++) {
            count[i] += count[i - 1];
        }
        for (let i = M - 1; i >= 0; i--) {
            const idx = p[i];
            const key = (dist[idx] >> shift) & 1023;
            count[key]--;
            pNext[count[key]] = idx;
        }
        const tmp = p;
        p = pNext;
        pNext = tmp;
    }

    const dp = new Int32Array(N + 1);
    // Para armazenar atualizações de arestas com mesma distância
    const updatedNodes = new Int32Array(N + 1);
    const updatedValues = new Int32Array(N + 1);
    let updateLen = 0;

    let ans = 0;

    let i = 0;
    while (i < M) {
        let j = i;
        const currentDist = dist[p[i]];
        while (j < M && dist[p[j]] === currentDist) {
            j++;
        }

        updateLen = 0;
        for (let k = i; k < j; k++) {
            const idx = p[k];
            const u = uEdge[idx];
            const v = vEdge[idx];

            if (u === 0) {
                // Do palácio para a tenda v
                const cand = 1 + dp[v];
                if (cand > ans) {
                    ans = cand;
                }
            } else {
                // Tenda u <-> Tenda v
                const candU = 1 + dp[v];
                const candV = 1 + dp[u];

                updatedNodes[updateLen] = u;
                updatedValues[updateLen] = candU;
                updateLen++;

                updatedNodes[updateLen] = v;
                updatedValues[updateLen] = candV;
                updateLen++;
            }
        }

        for (let k = 0; k < updateLen; k++) {
            const node = updatedNodes[k];
            const val = updatedValues[k];
            if (val > dp[node]) {
                dp[node] = val;
            }
        }

        i = j;
    }

    console.log(ans);
}

solve();
